        System.out.println("
=== 3. Armstrong Number Validation ===");
        int armstrongCandidate = 153;
        int t = armstrongCandidate, armstrongSum = 0;
        while (t > 0) {
            int digit = t % 10;
            armstrongSum += (digit * digit * digit);
            t /= 10;
        }
